-- Gold Query
SELECT T2.OpenDate FROM frpm AS T1 INNER JOIN schools AS T2 ON T1.CDSCode = T2.CDSCode ORDER BY T1."Enrollment (K-12)" DESC, T1.cdscode NULLS LAST, T2.cdscode NULLS LAST LIMIT 1;

/*
Gold Result:
('1980-05-10',)
*/

-- Prediction Query
SELECT OpenDate FROM schools WHERE CDSCode = (SELECT CDSCode FROM frpm WHERE "Enrollment (K-12)" = (SELECT MAX("Enrollment (K-12)") FROM frpm));

